from __future__ import absolute_import, division, print_function,\
    unicode_literals
from future import standard_library
from builtins import object
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler
from taf.ul.trs_e2e_fw.lib.traffic.generator.tool_base import ToolBase
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.traffic.generator.scapy_tool import ScapyTool
from taf.ul.trs_e2e_fw.lib.traffic.generator.trex.trex_hl import TrexHL

standard_library.install_aliases()
logger = BackgroundLogger.Instance()


class ToolFactory(object):

    def __init__(self, capture_device):
        self.config = ConfigHandler.get_config()
        self.capture_device = capture_device

    def get_tool_obj(self):
        logger.debug("getting tool object")
        return self._choose_generator_tool()

    def _choose_generator_tool(self):
        generator_tool = get_config_variable(['generators', self.capture_device, 'tool'])
        for tool in ToolBase.__subclasses__():
            if tool.check_tool(generator_tool):
                return tool(self.capture_device)
